-- Spec 24 · Module Tập luyện đợt 2: các bạn nhỏ theo 20 level, thẻ thử thách lên level, HLV giao bài về nhà, thư viện bài tập.
-- Tài liệu: docs/spec/24-module-tap-luyen-dot-2.md (anh Long chốt mục 7 ngày 23/11/2026).
-- Chỉ thêm bảng, hàm, cấu hình; thay hàm training_follow_student_merge để gồm bảng mới. Không tự cấp level.

-------------------------------------------------------------------------------
-- 0. Cấu hình
-------------------------------------------------------------------------------
insert into public.app_settings (key, value, description_vi, description_en, is_public) values
  ('training.child_self_entry_min_age', '11', 'Các bạn nhỏ từ tuổi này tự nhập kết quả tập luyện bằng tài khoản của mình; nhỏ hơn thì phụ huynh nhập', 'Minimum age for children to enter their own training results', true),
  ('training.points', '{"practice":10,"level_up":30,"assignment":20,"in_class":50}', 'Mức điểm mặc định (đợt 3 mới cộng vào ví): thẻ thường, thẻ lên level, bài về nhà, làm tại lớp', 'Default training points (credited from phase 3)', true)
on conflict do nothing;

-------------------------------------------------------------------------------
-- 1. Bảng
-------------------------------------------------------------------------------
create table public.training_challenges (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  level_number int not null check (level_number between 1 and 20),
  code text not null unique,
  kind text not null default 'level_up' check (kind in ('level_up', 'practice')),
  area text not null check (area in ('tee', 'approach', 'pitch', 'bunker', 'chip', 'putt_short', 'putt_mid', 'putt_long', 'formula', 'culture', 'other')),
  title_vi text not null,
  title_en text not null default '',
  how_vi text,
  how_en text,
  -- [{ "label_vi", "label_en"?, "attempts", "target", "provisional"? }]: mọi phần phải đạt target
  parts jsonb not null check (jsonb_typeof(parts) = 'array' and jsonb_array_length(parts) > 0),
  verify text not null check (verify in ('self', 'video_or_adult', 'coach')),
  points_rank int not null default 30 check (points_rank >= 0),
  points_reward int not null default 30 check (points_reward >= 0),
  is_provisional boolean not null default false,
  is_active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index training_challenges_level_idx on public.training_challenges (level_number, sort_order);

create table public.training_challenge_results (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  student_id uuid not null references public.students(id),
  challenge_id uuid not null references public.training_challenges(id),
  made int[] not null,
  video_url text check (video_url is null or video_url ~* '^https://(www\.|m\.)?(youtube\.com|youtu\.be)/'),
  -- passed: tự bấm đạt · below: chưa đạt chỉ tiêu · pending: chờ xác nhận · approved / rejected
  status text not null check (status in ('passed', 'below', 'pending', 'approved', 'rejected')),
  submitted_by uuid references public.profiles(user_id) on delete set null,
  submitted_as text not null check (submitted_as in ('guardian', 'student', 'coach')),
  reviewed_by uuid references public.profiles(user_id) on delete set null,
  reviewed_at timestamptz,
  review_note text,
  merge_trail uuid[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index training_challenge_results_student_idx on public.training_challenge_results (student_id, challenge_id, created_at desc);
create index training_challenge_results_pending_idx on public.training_challenge_results (status) where status = 'pending';

create table public.training_assignments (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  class_id uuid not null references public.classes(id),
  title_vi text not null check (btrim(title_vi) <> ''),
  body_vi text,
  challenge_id uuid references public.training_challenges(id),
  drill_id uuid,
  due_date date,
  points int not null default 20 check (points between 0 and 1000),
  in_class boolean not null default false,
  created_by uuid references public.profiles(user_id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index training_assignments_class_idx on public.training_assignments (class_id, created_at desc);

create table public.training_assignment_marks (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  assignment_id uuid not null references public.training_assignments(id) on delete cascade,
  student_id uuid not null references public.students(id),
  done_at timestamptz not null default now(),
  note text,
  marked_by uuid references public.profiles(user_id) on delete set null,
  confirmed_by uuid references public.profiles(user_id) on delete set null,
  confirmed_at timestamptz,
  merge_trail uuid[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (assignment_id, student_id)
);

create table public.training_drills (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  code text not null unique,
  title_vi text not null,
  title_en text not null default '',
  skill text not null check (skill in ('fitness', 'basics', 'putt', 'chip', 'pitch', 'bunker', 'full_swing', 'on_course', 'mental', 'rules')),
  form text not null default 'drill' check (form in ('game', 'drill', 'challenge', 'test', 'round')),
  audience text not null default 'all' check (audience in ('all', 'junior', 'adult')),
  level_from int check (level_from between 1 and 20),
  level_to int check (level_to between 1 and 20),
  -- home, club_only, small_room, range, course
  contexts text[] not null default '{}',
  minutes int check (minutes > 0),
  attempts int check (attempts > 0),
  target int check (target >= 0),
  unit_vi text,
  goal_vi text,
  steps jsonb not null default '[]' check (jsonb_typeof(steps) = 'array'),
  easier_vi text,
  harder_vi text,
  safety_vi text,
  video_url text,
  tags text[] not null default '{}',
  is_active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.training_assignments add constraint training_assignments_drill_fk foreign key (drill_id) references public.training_drills(id);

do $$
declare t text;
begin
  foreach t in array array['training_challenges', 'training_challenge_results', 'training_assignments', 'training_assignment_marks', 'training_drills'] loop
    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
  end loop;
  foreach t in array array['training_challenges', 'training_drills', 'training_assignments'] loop
    execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function public.audit_row()', t);
  end loop;
end $$;

-------------------------------------------------------------------------------
-- 2. Hàm quyền
-------------------------------------------------------------------------------
create or replace function public.training_student_age(p_student_id uuid)
returns int language sql stable security definer set search_path = public as $$
  select case when s.date_of_birth is not null then date_part('year', age(public.vn_today(), s.date_of_birth))::int
              when s.birth_year is not null then extract(year from public.vn_today())::int - s.birth_year end
  from public.students s where s.id = p_student_id
$$;

-- Tài khoản học viên của chính các con, đủ tuổi tự nhập
create or replace function public.training_is_self_student(p_student_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.my_student_id() = p_student_id
    and coalesce(public.training_student_age(p_student_id), 0) >= public.setting_int('training.child_self_entry_min_age', 11)
$$;

-- HLV của lớp các con đang học (lớp còn hoạt động), HLV trưởng, admin
create or replace function public.training_is_coach_of(p_student_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_center_staff() or exists (
    select 1 from public.enrollments e
    where e.student_id = p_student_id and e.status = 'active' and public.is_class_staff(e.class_id))
$$;

-- Được nhập kết quả cho học viên: người giám hộ quản lý được hồ sơ, hoặc chính các con từ 11 tuổi
create or replace function public.training_can_enter(p_student_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.training_enabled() and (public.can_manage_student(p_student_id) or public.training_is_self_student(p_student_id))
$$;

-- Được xem: người nhập được, chính các con (mọi tuổi), HLV của lớp
create or replace function public.training_can_view(p_student_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.training_can_enter(p_student_id) or public.my_student_id() = p_student_id or public.training_is_coach_of(p_student_id)
$$;

-------------------------------------------------------------------------------
-- 3. RLS
-------------------------------------------------------------------------------
create policy training_challenges_read on public.training_challenges for select to authenticated
  using (public.training_enabled() or public.my_student_id() is not null or public.has_role('coach') or public.is_center_staff());
create policy training_challenges_admin on public.training_challenges for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy training_drills_read on public.training_drills for select to authenticated
  using (public.training_enabled() or public.my_student_id() is not null or public.has_role('coach') or public.is_center_staff());
create policy training_drills_admin on public.training_drills for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Kết quả: chỉ đọc trực tiếp; ghi qua hàm
create policy training_results_read on public.training_challenge_results for select to authenticated using (public.training_can_view(student_id));

-- Bài giao: HLV của lớp quản lý; phụ huynh và các con trong lớp đọc
create policy training_assignments_staff on public.training_assignments for all to authenticated
  using (public.is_center_staff() or public.is_class_staff(class_id)) with check (public.is_center_staff() or public.is_class_staff(class_id));
create or replace function public.training_in_my_class(p_class_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.enrollments e where e.class_id = p_class_id and e.status = 'active'
                 and (public.can_manage_student(e.student_id) or public.my_student_id() = e.student_id))
$$;
create policy training_assignments_read on public.training_assignments for select to authenticated
  using (deleted_at is null and public.training_in_my_class(class_id));
create policy training_marks_read on public.training_assignment_marks for select to authenticated using (public.training_can_view(student_id));

-------------------------------------------------------------------------------
-- 4. Lên level: đủ thẻ level_up của level đang học → đề xuất chờ duyệt (không tự cấp)
-------------------------------------------------------------------------------
create or replace function public.training_current_level(p_student_id uuid)
returns int language sql stable security definer set search_path = public as $$
  select coalesce(l.number, 1) from public.students s left join public.levels l on l.id = s.current_level_id where s.id = p_student_id
$$;

-- Thẻ đã đạt: có lượt passed/approved
create or replace function public.training_challenge_done(p_student_id uuid, p_challenge_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.training_challenge_results r
                 where r.student_id = p_student_id and r.challenge_id = p_challenge_id and r.status in ('passed', 'approved'))
$$;

create or replace function public.training_check_level(p_student_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_level int := public.training_current_level(p_student_id);
  v_total int; v_done int; v_level_id uuid; v_rec uuid; v_actor uuid;
begin
  select count(*), count(*) filter (where public.training_challenge_done(p_student_id, c.id))
  into v_total, v_done
  from public.training_challenges c where c.level_number = v_level and c.kind = 'level_up' and c.is_active;
  if v_total = 0 or v_done < v_total then
    return jsonb_build_object('level', v_level, 'done', v_done, 'total', v_total, 'proposed', false);
  end if;
  select l.id into v_level_id from public.levels l join public.programs p on p.id = l.program_id
  where p.code = 'core20' and l.number = v_level;
  if v_level_id is null then return jsonb_build_object('level', v_level, 'done', v_done, 'total', v_total, 'proposed', false); end if;
  select id into v_rec from public.level_records
  where student_id = p_student_id and level_id = v_level_id and approval_status in ('pending', 'approved') limit 1;
  if v_rec is null then
    v_actor := case when exists (select 1 from public.profiles where user_id = auth.uid()) then auth.uid() end;
    insert into public.level_records (student_id, level_id, status, completed_at, source, proposed_by, approval_status, note)
    values (p_student_id, v_level_id, 'completed', public.vn_today(), 'assessment', v_actor, 'pending',
            'Đủ thẻ thử thách trên app Tập luyện')
    returning id into v_rec;
  end if;
  return jsonb_build_object('level', v_level, 'done', v_done, 'total', v_total, 'proposed', true, 'level_record_id', v_rec);
end $$;

-------------------------------------------------------------------------------
-- 5. Nộp kết quả, xác nhận
-------------------------------------------------------------------------------
create or replace function public.training_parts_met(p_parts jsonb, p_made int[])
returns boolean language sql immutable as $$
  select coalesce(array_length(p_made, 1), 0) = jsonb_array_length(p_parts)
     and not exists (select 1 from jsonb_array_elements(p_parts) with ordinality as x(p, i)
                     where coalesce(p_made[i], -1) < (p ->> 'target')::int or p_made[i] > (p ->> 'attempts')::int)
$$;

-- p_watched: người giám hộ xác nhận đã xem các con làm (thẻ video_or_adult)
create or replace function public.training_submit_result(p_student_id uuid, p_challenge_id uuid, p_made int[],
                                                         p_video_url text default null, p_watched boolean default false)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c public.training_challenges%rowtype;
  v_as text; v_status text; v_met boolean; v_id uuid; v_level jsonb := null;
begin
  select * into c from public.training_challenges where id = p_challenge_id and is_active;
  if c.id is null then raise exception 'challenge_not_found' using errcode = '22023'; end if;
  if public.can_manage_student(p_student_id) and public.training_enabled() then v_as := 'guardian';
  elsif public.training_is_self_student(p_student_id) and public.training_enabled() then v_as := 'student';
  elsif public.training_is_coach_of(p_student_id) then v_as := 'coach';
  else raise exception 'forbidden' using errcode = '42501';
  end if;
  if c.verify = 'coach' and v_as <> 'coach' then raise exception 'coach_only' using errcode = '22023'; end if;
  if exists (select 1 from unnest(p_made) m where m is null or m < 0) then raise exception 'invalid_made' using errcode = '22023'; end if;
  v_met := public.training_parts_met(c.parts, p_made);
  if coalesce(array_length(p_made, 1), 0) <> jsonb_array_length(c.parts) then raise exception 'invalid_made' using errcode = '22023'; end if;
  v_status := case
    when not v_met then 'below'
    when c.verify = 'self' then 'passed'
    when v_as = 'coach' then 'approved'
    when v_as = 'guardian' and p_watched then 'approved'
    else 'pending' end;
  insert into public.training_challenge_results (student_id, challenge_id, made, video_url, status, submitted_by, submitted_as,
                                                 reviewed_by, reviewed_at)
  values (p_student_id, c.id, p_made, nullif(btrim(coalesce(p_video_url, '')), ''), v_status,
          case when exists (select 1 from public.profiles where user_id = auth.uid()) then auth.uid() end, v_as,
          case when v_status = 'approved' then auth.uid() end, case when v_status = 'approved' then now() end)
  returning id into v_id;
  if v_status in ('passed', 'approved') and c.kind = 'level_up' then v_level := public.training_check_level(p_student_id); end if;
  return jsonb_build_object('id', v_id, 'status', v_status, 'level', v_level);
end $$;

-- Xác nhận lượt chờ: người giám hộ quản lý hồ sơ (không xác nhận lượt chính mình nộp... được phép, vì đã xem) hoặc HLV của lớp
create or replace function public.training_review_result(p_result_id uuid, p_approve boolean, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare r public.training_challenge_results%rowtype; c public.training_challenges%rowtype; v_level jsonb := null;
begin
  select * into r from public.training_challenge_results where id = p_result_id for update;
  if r.id is null or r.status <> 'pending' then raise exception 'not_pending' using errcode = '22023'; end if;
  select * into c from public.training_challenges where id = r.challenge_id;
  if not (public.training_is_coach_of(r.student_id) or (c.verify = 'video_or_adult' and public.can_manage_student(r.student_id))) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  update public.training_challenge_results
  set status = case when p_approve then 'approved' else 'rejected' end, reviewed_by = auth.uid(), reviewed_at = now(),
      review_note = nullif(btrim(coalesce(p_note, '')), '')
  where id = r.id;
  if p_approve and c.kind = 'level_up' then v_level := public.training_check_level(r.student_id); end if;
  return jsonb_build_object('status', case when p_approve then 'approved' else 'rejected' end, 'level', v_level);
end $$;

-- HLV chấm thẻ (thường là thẻ level 1–9) cho nhiều bạn cùng lúc
create or replace function public.training_coach_mark(p_challenge_id uuid, p_student_ids uuid[], p_passed boolean, p_note text default null)
returns int language plpgsql volatile security definer set search_path = public as $$
declare c public.training_challenges%rowtype; s uuid; n int := 0; v_made int[];
begin
  select * into c from public.training_challenges where id = p_challenge_id and is_active;
  if c.id is null then raise exception 'challenge_not_found' using errcode = '22023'; end if;
  select array_agg(case when p_passed then (p ->> 'target')::int else 0 end order by i) into v_made
  from jsonb_array_elements(c.parts) with ordinality as x(p, i);
  foreach s in array p_student_ids loop
    if not public.training_is_coach_of(s) then raise exception 'forbidden' using errcode = '42501'; end if;
    insert into public.training_challenge_results (student_id, challenge_id, made, status, submitted_by, submitted_as, reviewed_by, reviewed_at, review_note)
    values (s, c.id, v_made, case when p_passed then 'approved' else 'rejected' end, auth.uid(), 'coach', auth.uid(), now(),
            nullif(btrim(coalesce(p_note, '')), ''));
    if p_passed and c.kind = 'level_up' then perform public.training_check_level(s); end if;
    n := n + 1;
  end loop;
  return n;
end $$;

-------------------------------------------------------------------------------
-- 6. Bài về nhà
-------------------------------------------------------------------------------
create or replace function public.training_mark_assignment(p_assignment_id uuid, p_student_id uuid, p_done boolean, p_note text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare a public.training_assignments%rowtype; v_coach boolean;
begin
  select * into a from public.training_assignments where id = p_assignment_id and deleted_at is null;
  if a.id is null then raise exception 'assignment_not_found' using errcode = '22023'; end if;
  if not exists (select 1 from public.enrollments e where e.class_id = a.class_id and e.student_id = p_student_id and e.status = 'active') then
    raise exception 'not_in_class' using errcode = '22023';
  end if;
  v_coach := public.is_center_staff() or public.is_class_staff(a.class_id);
  if not (v_coach or public.training_can_enter(p_student_id)) then raise exception 'forbidden' using errcode = '42501'; end if;
  if not p_done then
    -- Bỏ đánh dấu: HLV bỏ được mọi dòng; phụ huynh, các con chỉ bỏ dòng chưa được HLV xác nhận
    delete from public.training_assignment_marks
    where assignment_id = a.id and student_id = p_student_id and (v_coach or confirmed_at is null);
    return;
  end if;
  insert into public.training_assignment_marks (assignment_id, student_id, note, marked_by, confirmed_by, confirmed_at)
  values (a.id, p_student_id, nullif(btrim(coalesce(p_note, '')), ''), auth.uid(),
          case when v_coach then auth.uid() end, case when v_coach then now() end)
  on conflict (assignment_id, student_id) do update
  set note = coalesce(excluded.note, training_assignment_marks.note),
      confirmed_by = coalesce(training_assignment_marks.confirmed_by, excluded.confirmed_by),
      confirmed_at = coalesce(training_assignment_marks.confirmed_at, excluded.confirmed_at);
end $$;

create or replace function public.training_confirm_marks(p_assignment_id uuid, p_student_ids uuid[])
returns int language plpgsql volatile security definer set search_path = public as $$
declare a public.training_assignments%rowtype; n int;
begin
  select * into a from public.training_assignments where id = p_assignment_id and deleted_at is null;
  if a.id is null then raise exception 'assignment_not_found' using errcode = '22023'; end if;
  if not (public.is_center_staff() or public.is_class_staff(a.class_id)) then raise exception 'forbidden' using errcode = '42501'; end if;
  update public.training_assignment_marks set confirmed_by = auth.uid(), confirmed_at = now()
  where assignment_id = a.id and student_id = any(p_student_ids) and confirmed_at is null;
  get diagnostics n = row_count;
  return n;
end $$;

-------------------------------------------------------------------------------
-- 7. Màn HLV: tiến độ lớp và lượt chờ xác nhận
-------------------------------------------------------------------------------
create or replace function public.training_class_progress(p_class_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.is_center_staff() or public.is_class_staff(p_class_id)) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(x order by x ->> 'full_name') from (
    select jsonb_build_object(
      'student_id', s.id, 'full_name', s.full_name, 'student_code', s.student_code,
      'level', public.training_current_level(s.id),
      'total', (select count(*) from public.training_challenges c where c.level_number = public.training_current_level(s.id) and c.kind = 'level_up' and c.is_active),
      'done', (select count(*) from public.training_challenges c where c.level_number = public.training_current_level(s.id) and c.kind = 'level_up' and c.is_active
               and public.training_challenge_done(s.id, c.id)),
      'pending', (select count(*) from public.training_challenge_results r where r.student_id = s.id and r.status = 'pending'),
      'proposed', exists (select 1 from public.level_records lr join public.levels l on l.id = lr.level_id
                          where lr.student_id = s.id and lr.approval_status = 'pending' and l.number = public.training_current_level(s.id))
    ) x
    from public.enrollments e join public.students s on s.id = e.student_id
    where e.class_id = p_class_id and e.status = 'active' and s.deleted_at is null) q), '[]');
end $$;

create or replace function public.training_class_pending(p_class_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.is_center_staff() or public.is_class_staff(p_class_id)) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', r.id, 'student_id', s.id, 'full_name', s.full_name, 'challenge_code', c.code, 'title_vi', c.title_vi, 'level', c.level_number,
      'parts', c.parts, 'made', to_jsonb(r.made), 'video_url', r.video_url, 'submitted_as', r.submitted_as, 'created_at', r.created_at)
      order by r.created_at)
    from public.training_challenge_results r
    join public.training_challenges c on c.id = r.challenge_id
    join public.students s on s.id = r.student_id
    where r.status = 'pending' and exists (select 1 from public.enrollments e where e.class_id = p_class_id and e.student_id = r.student_id and e.status = 'active')), '[]');
end $$;

-------------------------------------------------------------------------------
-- 8. Gộp hồ sơ: thêm bảng mới vào danh sách đi theo
-------------------------------------------------------------------------------
create or replace function public.training_follow_student_merge()
returns trigger language plpgsql security definer set search_path = public as $$
declare t text; k uuid := new.merged_into_student_id;
begin
  if old.merged_into_student_id is null and new.merged_into_student_id is not null then
    if exists (select 1 from public.training_goals where student_id = k and status = 'active') then
      update public.training_goals set status = 'replaced', ended_at = now() where student_id = old.id and status = 'active';
    end if;
    -- Đánh dấu bài giao trùng (cùng bài) giữ dòng của hồ sơ giữ lại
    delete from public.training_assignment_marks m where m.student_id = old.id
      and exists (select 1 from public.training_assignment_marks k2 where k2.student_id = k and k2.assignment_id = m.assignment_id);
    foreach t in array array['training_goals', 'training_intake_tests', 'training_session_logs', 'round_stats', 'club_distances',
                             'training_challenge_results', 'training_assignment_marks'] loop
      execute format('update public.%I set student_id = $1, merge_trail = merge_trail || $2 where student_id = $2', t) using k, old.id;
    end loop;
  elsif old.merged_into_student_id is not null and new.merged_into_student_id is null then
    foreach t in array array['training_goals', 'training_intake_tests', 'training_session_logs', 'round_stats', 'club_distances',
                             'training_challenge_results', 'training_assignment_marks'] loop
      execute format('update public.%I set student_id = $1, merge_trail = merge_trail[1:cardinality(merge_trail) - 1]
                      where merge_trail[cardinality(merge_trail)] = $1', t) using old.id;
    end loop;
  end if;
  return null;
end $$;

-------------------------------------------------------------------------------
-- 9. Quyền gọi hàm
-------------------------------------------------------------------------------
do $$
declare f text;
begin
  revoke execute on function public.training_check_level(uuid) from public, anon, authenticated;
  foreach f in array array[
    'public.training_student_age(uuid)', 'public.training_is_self_student(uuid)', 'public.training_is_coach_of(uuid)',
    'public.training_can_enter(uuid)', 'public.training_can_view(uuid)', 'public.training_current_level(uuid)',
    'public.training_challenge_done(uuid, uuid)', 'public.training_parts_met(jsonb, int[])',
    'public.training_submit_result(uuid, uuid, int[], text, boolean)', 'public.training_review_result(uuid, boolean, text)',
    'public.training_coach_mark(uuid, uuid[], boolean, text)', 'public.training_mark_assignment(uuid, uuid, boolean, text)',
    'public.training_confirm_marks(uuid, uuid[])', 'public.training_in_my_class(uuid)', 'public.training_class_progress(uuid)', 'public.training_class_pending(uuid)'
  ] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;

