ng phải rồi sang trái, giữ đầu đứng yên.","Mỗi hiệp 15 lần."],"tags":[],"audience":"all","sort_order":1},{"code":"stork","title_vi":"Đứng một chân","skill":"fitness","contexts":["home","club_only","small_room"],"minutes":5,"attempts":4,"target":4,"unit_vi":"lượt","steps":["Đứng một chân, hai tay khoanh trước ngực.","Giữ 30 giây rồi đổi chân.","Muốn khó hơn thì nhắm mắt."],"tags":[],"audience":"all","sort_order":2},{"code":"plank","title_vi":"Plank giữ thân","skill":"fitness","contexts":["home","club_only","small_room"],"minutes":5,"attempts":3,"target":3,"unit_vi":"hiệp","steps":["Chống khuỷu tay, người thẳng từ vai đến gót.","Giữ 30 giây mỗi hiệp."],"tags":["home21-day8","home21-day18","home21-day20"],"audience":"all","sort_order":3},{"code":"grip","title_vi":"Cầm gậy và setup","skill":"basics","contexts":["club_only","small_room"],"minutes":5,"attempts":10,"target":8,"unit_vi":"lần","steps":["Cầm gậy, vào tư thế setup.","Tự kiểm tra ba điểm: grip, tư thế, hướng ngắm.","Bỏ gậy xuống rồi làm lại."],"tags":["home21-day4","home21-day8","home21-day12","home21-day17"],"audience":"all","sort_order":4},{"code":"mirror","title_vi":"Swing chậm trước gương","skill":"full_swing","contexts":["club_only","small_room"],"minutes":10,"attempts":10,"target":10,"unit_vi":"lần","steps":["Đứng trước gương, không cần bóng.","Swing chậm, giữ tư thế finish 3 giây.","Đạt khi giữ thăng bằng đủ 3 giây."],"tags":["home21-day3"],"audience":"all","sort_order":5},{"code":"clock","title_vi":"Đồng hồ 1 mét","skill":"putt","contexts":["small_room","range","course"],"minutes":10,"attempts":6,"target":6,"unit_vi":"bóng","steps":["Đặt 6 bóng quanh lỗ hoặc cốc, cách 1 m như mặt đồng hồ.","Putt lần lượt từng bóng.","Đạt khi vào cả 6 bóng."],"tags":[],"audience":"all","sort_order":6},{"code":"ladder","title_vi":"Bậc thang putt xa","skill":"putt","contexts":["small_room","range","course"],"minutes":10,"attempts":9,"target":6,"unit_vi":"bóng","steps":["Đặt mốc 2, 4 và 6 m.","Mỗi mốc putt 3 bóng.","Bóng dừng trong 50 cm quanh lỗ là đạt."],"tags":[],"audience":"all","sort_order":7},{"code":"bucket","title_vi":"Chip vào xô","skill":"chip","contexts":["small_room","range"],"minutes":10,"attempts":10,"target":4,"unit_vi":"bóng","steps":["Đặt xô hoặc rổ cách 5 m.","Chip 10 bóng.","Bóng rơi vào hoặc chạm xô là đạt."],"tags":["home21-day5","home21-day17"],"audience":"all","sort_order":8},{"code":"landing","title_vi":"Chip chọn điểm rơi","skill":"chip","contexts":["range","course"],"minutes":10,"attempts":10,"target":5,"unit_vi":"bóng","steps":["Đặt một chiếc khăn làm điểm rơi, cách 3 bước.","Chip 10 bóng.","Bóng chạm khăn trước khi lăn là đạt."],"tags":[],"audience":"all","sort_order":9},{"code":"pitch3","title_vi":"Pitch ba khoảng cách","skill":"pitch","contexts":["range"],"minutes":15,"attempts":9,"target":5,"unit_vi":"bóng","steps":["Chọn ba mục tiêu 30, 40 và 50 m.","Mỗi mục tiêu đánh 3 bóng.","Bóng dừng trong vòng 6 m quanh mục tiêu là đạt."],"tags":[],"audience":"all","sort_order":10},{"code":"fairway","title_vi":"Driver vào fairway","skill":"full_swing","contexts":["range"],"minutes":15,"attempts":10,"target":6,"unit_vi":"bóng","steps":["Chọn hai mốc làm mép fairway, rộng khoảng 30 m.","Đánh 10 cú driver, cú nào cũng làm đủ routine.","Bóng dừng giữa hai mốc là đạt."],"tags":[],"audience":"all","sort_order":11},{"code":"updown","title_vi":"Up and down quanh green","skill":"chip","contexts":["range","course"],"minutes":15,"attempts":6,"target":3,"unit_vi":"lượt","steps":["Thả bóng ở 6 vị trí quanh green.","Chip rồi putt đến khi bóng vào lỗ.","Vào lỗ trong 2 gậy là đạt."],"tags":[],"audience":"all","sort_order":12},{"code":"nine","title_vi":"Chơi 9 hố ghi điểm","skill":"on_course","contexts":["course"],"minutes":120,"attempts":9,"target":5,"unit_vi":"hố","steps":["Chơi 9 hố như thi đấu.","Hết mỗi hố, bấm theo điểm của hố đó."],"tags":[],"audience":"all","sort_order":13},{"code":"book","title_vi":"Đường ray hai cuốn sách","skill":"putt","contexts":["club_only","small_room"],"minutes":10,"attempts":3,"target":3,"unit_vi":"hiệp","steps":["Đặt hai cuốn sách song song, khe vừa lọt đầu gậy putter.","Đánh putt không bóng: 25 lượt hai tay, 25 lượt tay phải, 25 lượt tay trái.","Chạm sách nghĩa là đường gậy chưa thẳng hoặc mặt gậy chưa vuông."],"tags":["home21-day1","home21-day15"],"audience":"all","sort_order":14},{"code":"cup5","title_vi":"Putt vào cốc 5 ft","skill":"putt","contexts":["small_room"],"minutes":15,"attempts":75,"target":45,"unit_vi":"bóng","steps":["Đặt cốc nằm nghiêng làm lỗ, cách 5 ft (1,5 m).","25 bóng hai tay, 25 bóng tay phải, 25 bóng tay trái.","Bóng trượt chỉ nên đi quá cốc 30–45 cm. Ghi tổng số bóng vào cốc và cố phá kỷ lục lần sau."],"tags":["home21-day2","home21-day12"],"audience":"all","sort_order":15},{"code":"towel","title_vi":"Chip vào khăn","skill":"chip","contexts":["small_room","range"],"minutes":15,"attempts":50,"target":20,"unit_vi":"bóng","steps":["Đặt khăn cách 10 ft (3 m). Chip để bóng rơi trúng khăn; bóng lăn ra ngoài không sao.","Muốn khó hơn: lùi khăn ra 15 ft hoặc gấp khăn nhỏ lại.","Ghi số bóng rơi trúng khăn trên 50 bóng."],"tags":["home21-day1","home21-day10","home21-day21"],"audience":"all","sort_order":16},{"code":"bottle","title_vi":"Chip đổ chai nước","skill":"chip","contexts":["small_room"],"minutes":10,"attempts":4,"target":4,"unit_vi":"mốc","steps":["Đặt chai nước ở 5, 12, 20 và 28 ft.","Chip đến khi đổ chai ở từng mốc rồi sang mốc tiếp.","Ghi số lượt cần cho mỗi mốc để lần sau phá kỷ lục."],"tags":["home21-day2","home21-day14"],"audience":"all","sort_order":17},{"code":"takeaway","title_vi":"Đẩy sách khi lên gậy","skill":"full_swing","contexts":["club_only","small_room"],"minutes":10,"attempts":2,"target":2,"unit_vi":"hiệp","steps":["Đặt cuốn sách nhẹ hoặc quả bóng ngay sau đầu gậy ở tư thế setup.","Lên gậy (takeaway) đẩy sách lùi lại, tay và vai chuyển động cùng nhau.","2 hiệp, mỗi hiệp 25 lần; nghỉ 3 phút giữa hiệp, tập bụng nhẹ."],"tags":["home21-day3","home21-day11"],"audience":"all","sort_order":18},{"code":"ladder4","title_vi":"Chip bậc thang 4 mục tiêu","skill":"chip","contexts":["small_room","range"],"minutes":10,"attempts":4,"target":4,"unit_vi":"mục tiêu","steps":["Đặt 4 khăn nhỏ ở 3, 6, 9, 12 ft.","Trúng khăn gần nhất mới được chuyển sang khăn tiếp theo.","Tự đặt giới hạn 20 lượt cho cả 4 mục tiêu; hết lượt thì làm lại từ đầu. Biến thể: đi ngược từ xa về gần."],"tags":["home21-day4","home21-day10","home21-day12","home21-day15"],"audience":"all","sort_order":19},{"code":"coin4","title_vi":"Bốn đồng xu","skill":"putt","contexts":["small_room"],"minutes":10,"attempts":4,"target":4,"unit_vi":"cạnh","steps":["Đặt 4 đồng xu thành hình vuông cạnh 3 ft.","Putt từ đồng xu này sang đồng xu kế tiếp, cố cho bóng dừng ngay trên đồng xu.","Hỏng một cạnh thì quay lại đồng xu đầu."],"tags":["home21-day4","home21-day21"],"audience":"all","sort_order":20},{"code":"wall","title_vi":"Swing sát tường","skill":"full_swing","contexts":["club_only","small_room"],"minutes":10,"attempts":3,"target":3,"unit_vi":"hiệp","steps":["Đứng quay mặt vào tường, đầu gậy sắt cách tường một khoảng nhỏ.","Swing chậm nửa lên, nửa xuống; tường buộc gậy đi từ trong ra, vuông lúc chạm, rồi vào trong.","Mỗi hiệp 10 lần."],"tags":["home21-day5"],"audience":"all","sort_order":21},{"code":"ace","title_vi":"Putt lên lá bài","skill":"putt","contexts":["small_room","range"],"minutes":15,"attempts":4,"target":4,"unit_vi":"mốc","steps":["Đặt một lá bài cách 10 ft.","Putt cho bóng dừng trên lá bài, xong thì lùi ra 15, 20, 25 ft.","Ghi số lượt cần cho mỗi mốc."],"tags":["home21-day6"],"audience":"all","sort_order":22},{"code":"box5","title_vi":"5 bóng trong hộp","skill":"putt","contexts":["small_room","range"],"minutes":10,"attempts":5,"target":5,"unit_vi":"bóng","steps":["Dán băng dính thành hộp 2×2 ft, bỏ trống cạnh phía người putt.","Bóng 1 vừa qua vạch, mỗi bóng sau đi xa hơn bóng trước một chút, cả 5 bóng nằm trong hộp.","Bóng ngắn hơn bóng trước hoặc ra khỏi hộp thì làm lại."],"tags":["home21-day6","home21-day19"],"audience":"all","sort_order":23},{"code":"hotshot","title_vi":"Chip ghi điểm 4 mục tiêu","skill":"chip","contexts":["small_room","range"],"minutes":10,"attempts":100,"target":30,"unit_vi":"điểm","steps":["Đặt mục tiêu ở 4, 8, 12, 16 ft, lần lượt 1, 3, 5, 10 điểm.","10 bóng, tự chọn mục tiêu để ghi điểm cao nhất (tối đa 100).","Ghi tổng điểm và cố phá kỷ lục."],"tags":["home21-day7"],"audience":"all","sort_order":24},{"code":"teeputt","title_vi":"Putt đổ tee","skill":"putt","contexts":["small_room","range"],"minutes":20,"attempts":20,"target":10,"unit_vi":"ft","steps":["Cắm ngược một chiếc tee làm mục tiêu.","Bắt đầu từ 3 ft, đổ tee xong thì lùi 1 ft: 4, 5, 6 ft…","Ghi khoảng cách xa nhất đã đổ được tee (mục tiêu 20 ft)."],"tags":["home21-day7","home21-day20"],"audience":"all","sort_order":25},{"code":"twoball","title_vi":"Putt hai bóng kiểm tra mặt gậy","skill":"putt","contexts":["small_room","range"],"minutes":10,"attempts":25,"target":12,"unit_vi":"lượt","steps":["Đặt hai bóng chồng lên nhau theo chiều dọc mặt gậy, mỗi bóng chiếm nửa mặt gậy.","Hai bóng lăn cùng nhau: mặt gậy vuông. Bóng dưới đi trước: mặt gậy mở. Bóng trên đi trước: mặt gậy đóng.","Ghi số lượt hai bóng lăn cùng nhau trên 25 lượt."],"tags":["home21-day9"],"audience":"all","sort_order":26},{"code":"walllag","title_vi":"Putt sát tường","skill":"putt","contexts":["small_room"],"minutes":15,"attempts":7,"target":5,"unit_vi":"mốc","steps":["Putt cho bóng dừng càng sát tường càng tốt mà không chạm tường.","Bắt đầu 8 ft, lùi mỗi lần 4 ft: 12, 16, 20, 24, 28, 32 ft.","Tính đạt khi bóng dừng trong khoảng một bàn tay tính từ tường."],"tags":["home21-day10"],"audience":"all","sort_order":27},{"code":"shoulder","title_vi":"Xoay vai ngồi ghế","skill":"fitness","contexts":["club_only","small_room"],"minutes":5,"attempts":3,"target":3,"unit_vi":"hiệp","steps":["Ngồi thẳng trên ghế, hai bàn chân đặt chắc, hai tay giữ gậy ngang trước mặt.","Xoay thân trên sang phải rồi sang trái, giữ hông và chân yên.","Xoay chậm, mỗi lần cố xoay xa hơn một chút. Mỗi hiệp 10 lần mỗi bên."],"tags":["home21-day11","home21-day18"],"audience":"all","sort_order":28},{"code":"eyeline","title_vi":"Kiểm tra đường mắt","skill":"putt","contexts":["small_room","range"],"minutes":5,"attempts":10,"target":7,"unit_vi":"lần","steps":["Vào tư thế putt, tay cầm thêm một quả bóng đưa lên sát mắt.","Thả bóng: rơi trúng bóng dưới đất là mắt đang thẳng trên đường bóng.","Rơi trong hoặc ngoài nghĩa là đang nhìn lệch, dễ đẩy hoặc kéo bóng."],"tags":["home21-day17"],"audience":"all","sort_order":29},{"code":"eyesclosed","title_vi":"Nhắm mắt cảm nhận lực","skill":"putt","contexts":["small_room","range"],"minutes":10,"attempts":10,"target":5,"unit_vi":"lượt","steps":["Chọn hành lang hoặc phòng dài, setup như một cú lag putt.","Nhắm mắt rồi putt, đoán bóng đi bao xa trước khi mở mắt.","Đoán đúng trong khoảng một bước chân là đạt."],"tags":["home21-day19"],"audience":"all","sort_order":30},{"code":"ruler","title_vi":"Thước đo biên độ putt","skill":"putt","contexts":["small_room"],"minutes":10,"attempts":3,"target":3,"unit_vi":"hiệp","steps":["Đặt thước dài vuông góc với putter.","Lên gậy đến một vạch, theo gậy đúng bằng biên độ đó.","Đổi biên độ, quan sát bóng đi xa bao nhiêu. Mỗi hiệp 20 lượt."],"tags":["home21-day20"],"audience":"all","sort_order":31},{"code":"onehand","title_vi":"Putt một tay 3 ft","skill":"putt","contexts":["small_room","range"],"minutes":10,"attempts":6,"target":5,"unit_vi":"hiệp","steps":["Putt 3 ft chỉ bằng tay phải: 3 hiệp, mỗi hiệp 10 bóng; rồi đổi tay trái.","Giữ đường gậy thẳng và mặt gậy vuông với mục tiêu.","Hiệp đạt khi vào ít nhất 7/10."],"tags":["home21-day13"],"audience":"all","sort_order":32},{"code":"lagbox","title_vi":"Lag putt ba ô","skill":"putt","contexts":["small_room","range"],"minutes":10,"attempts":30,"target":18,"unit_vi":"điểm","steps":["Kẻ 3 ô liền nhau mỗi ô 2×2 ft, từ 20 đến 26 ft.","10 bóng: dừng ở ô giữa 3 điểm; ô đầu hoặc ô cuối 1 điểm; ra ngoài trừ 2 điểm.","Ghi tổng điểm (tối đa 30)."],"tags":["home21-day16"],"audience":"all","sort_order":33},{"code":"video","title_vi":"Quay video swing","skill":"full_swing","contexts":["small_room","range"],"minutes":15,"attempts":1,"target":1,"unit_vi":"lần","steps":["Đặt điện thoại ở hai góc: chính diện và dọc đường bóng.","Quay vài cú swing, xem chậm từng vị trí: setup, lên gậy, đỉnh, chạm bóng, kết thúc.","Có thể gửi video cho HLV nhận xét."],"tags":["home21-day14"],"audience":"all","sort_order":34},{"code":"stretch","title_vi":"Giãn cơ khởi động golf","skill":"fitness","contexts":["home","club_only","small_room","range","course"],"minutes":10,"attempts":11,"target":11,"unit_vi":"động tác","steps":["Xoay thân chậm, xoay tay tròn, giãn vai ngực với gậy, giãn tay sau (tricep).","Giãn lưng quỳ gối, giãn lưng dưới nằm, giãn bướm, giãn đùi trước.","Cúi chạm mũi chân 10–15 giây, xoay cổ tay với gậy, giãn đùi trong sang hai bên."],"tags":["home21-day8","home21-day9","home21-day13","home21-day16","home21-day18"],"audience":"all","sort_order":35},{"code":"green","title_vi":"Green giả định","skill":"pitch","contexts":["range"],"minutes":20,"attempts":30,"target":10,"unit_vi":"bóng","steps":["Chọn mục tiêu 50–125 y, tưởng tượng một green quanh mục tiêu.","Đánh số bóng định trước, đếm số cú vào green như trên sân.","Ghi số cú vào green và cố cải thiện mỗi buổi."],"tags":[],"audience":"all","sort_order":36},{"code":"traj","title_vi":"Ba quỹ đạo bóng","skill":"full_swing","contexts":["range"],"minutes":20,"attempts":30,"target":15,"unit_vi":"bóng","steps":["10 bóng quỹ đạo cao, 10 bóng trung bình, 10 bóng thấp.","Biến thể: dùng gậy sắt 7 đánh nhẹ tới mục tiêu ngắn hơn bình thường.","Ghi số bóng ra đúng quỹ đạo định đánh."],"tags":[],"audience":"all","sort_order":37},{"code":"gate","title_vi":"Cổng tee giữa mặt gậy","skill":"full_swing","contexts":["range"],"minutes":15,"attempts":20,"target":14,"unit_vi":"bóng","steps":["Cắm một tee sát gót gậy, một tee sát mũi gậy khi setup.","Swing chậm không bóng, rồi nửa swing có bóng, rồi swing đủ.","Đạt khi qua cổng không chạm tee nào."],"tags":[],"audience":"all","sort_order":38},{"code":"routine","title_vi":"Bài range 100–125–150 y","skill":"full_swing","contexts":["range"],"minutes":30,"attempts":45,"target":20,"unit_vi":"bóng","steps":["Đặt que căn hướng. 10 bóng tới 100 y, 10 bóng tới 125 y, 10 bóng tới 150 y.","15 bóng tiếp theo đổi mục tiêu sau mỗi bóng 100, 125, 150 y.","Swing êm, không cố đánh mạnh; ghi số bóng đúng mục tiêu."],"tags":[],"audience":"all","sort_order":39},{"code":"circle","title_vi":"Vòng tròn 5 tee","skill":"putt","contexts":["range","course"],"minutes":15,"attempts":50,"target":40,"unit_vi":"bóng","steps":["Cắm 5 tee quanh lỗ cách 3 ft.","Putt lần lượt quanh vòng; đi 10 vòng là 50 bóng.","Bản áp lực: phải vào liên tiếp, trượt là đếm lại. Ghi số bóng vào."],"tags":[],"audience":"all","sort_order":40},{"code":"line","title_vi":"Bậc thang putt 3–6–9–12 ft","skill":"putt","contexts":["range","course"],"minutes":15,"attempts":4,"target":4,"unit_vi":"bóng","steps":["Cắm tee ở 3, 6, 9, 12 ft trên một đường thẳng.","Putt vào lần lượt từ gần ra xa; trượt là quay về 3 ft.","Biến thể: đi ngược từ 12 ft."],"tags":[],"audience":"all","sort_order":41},{"code":"onetwo","title_vi":"1–2–3 ft, mỗi mốc 10 liên tiếp","skill":"putt","contexts":["range","course","small_room"],"minutes":15,"attempts":3,"target":3,"unit_vi":"mốc","steps":["Vào 10 bóng liên tiếp từ 1 ft, rồi 2 ft, rồi 3 ft.","Trượt bất kỳ lúc nào thì làm lại mốc đó.","Đủ 30 bóng liên tiếp là xong bài."],"tags":[],"audience":"all","sort_order":42},{"code":"mini9","title_vi":"Sân putt 9 hố","skill":"putt","contexts":["range","course"],"minutes":20,"attempts":9,"target":7,"unit_vi":"hố","steps":["Putt qua lại giữa 9 lỗ trên green tập như một sân mini.","1 putt là birdie, 2 putt là par, 3 putt là bogey.","Mục tiêu: dưới 18 putt cho 9 hố."],"tags":[],"audience":"all","sort_order":43},{"code":"cage","title_vi":"Lồng ba gậy","skill":"putt","contexts":["range","course"],"minutes":15,"attempts":20,"target":14,"unit_vi":"bóng","steps":["Đặt 3 gậy thành lồng quanh lỗ, gậy phía sau cách lỗ khoảng 2 ft.","Putt từ phía mở; bóng trượt phải nằm trong lồng, không chạm gậy.","Ghi số bóng vào lỗ hoặc dừng trong lồng."],"tags":[],"audience":"all","sort_order":44},{"code":"points","title_vi":"Chip tính điểm 1–2–3 ft","skill":"chip","contexts":["range","course"],"minutes":15,"attempts":30,"target":15,"unit_vi":"điểm","steps":["Đánh dấu vòng 1, 2, 3 ft quanh lỗ.","10 bóng: trong 1 ft được 3 điểm, 2 ft được 2 điểm, 3 ft được 1 điểm.","Ghi tổng điểm (tối đa 30)."],"tags":[],"audience":"all","sort_order":45},{"code":"past","title_vi":"Chip qua bóng trước","skill":"chip","contexts":["range","course"],"minutes":10,"attempts":10,"target":6,"unit_vi":"bóng","steps":["Chip một bóng lên green.","Bóng sau phải dừng xa hơn bóng trước một chút.","Biến thể khó: hai bóng dừng sát cạnh nhau."],"tags":[],"audience":"all","sort_order":46},{"code":"p100","title_vi":"100 putt liên tiếp 3 ft","skill":"mental","contexts":["range","course","small_room"],"minutes":30,"attempts":100,"target":100,"unit_vi":"bóng","steps":["Putt 3 ft, đếm số bóng vào liên tiếp; trượt là đếm lại từ 0.","Ghi chuỗi dài nhất của buổi.","Đạt 100 thì chuyển sang 4, 5, 6 ft."],"tags":[],"audience":"all","sort_order":47},{"code":"pressure","title_vi":"Chip áp lực 10/10","skill":"mental","contexts":["range","course"],"minutes":15,"attempts":10,"target":10,"unit_vi":"bóng","steps":["Từ rough sát green, chip 10 bóng tới một lỗ gần.","Cả 10 bóng phải dừng trong vòng 3 ft.","Làm tiếp với lỗ giữa và lỗ xa; dễ quá thì tăng lên 15, 20 bóng."],"tags":[],"audience":"all","sort_order":48},{"code":"worse","title_vi":"Chơi hai bóng, chọn bóng tệ hơn","skill":"mental","contexts":["course"],"minutes":90,"attempts":9,"target":3,"unit_vi":"hố","steps":["Mỗi vị trí đánh hai bóng, chọn bóng tệ hơn để đánh tiếp, kể cả khi putt.","Cách này rèn bình tĩnh khi gặp tình huống khó.","Hết mỗi hố, bấm theo điểm của hố."],"tags":[],"audience":"all","sort_order":49},{"code":"ladder-chip-1","title_vi":"Thang chip bậc 1","skill":"chip","contexts":["range"],"minutes":null,"attempts":105,"target":43,"unit_vi":"bóng","steps":["Từ fringe: chip vào khăn 5, 10, 20 ft (mỗi mốc 20 bóng): đạt 25/60","Từ rough cách green 5 y: chip vào khăn 5, 10, 20 ft (mỗi mốc 10): đạt 12/30","Up & down từ fringe tới lỗ gần, giữa, xa (mỗi lỗ 5 lượt): đạt 6/15"],"tags":["ladder-chip"],"audience":"all","sort_order":1001},{"code":"ladder-chip-2","title_vi":"Thang chip bậc 2","skill":"chip","contexts":["range"],"minutes":null,"attempts":105,"target":52,"unit_vi":"bóng","steps":["Từ fringe: chip vào khăn 10, 20, 30 ft (mỗi mốc 10): đạt 15/30","Từ rough 5 y: chip vào khăn 5, 10, 20, 30 ft (mỗi mốc 15): đạt 30/60","Up & down từ fringe tới lỗ gần, giữa, xa: đạt 7/15"],"tags":["ladder-chip"],"audience":"all","sort_order":1002},{"code":"ladder-chip-3","title_vi":"Thang chip bậc 3","skill":"chip","contexts":["range"],"minutes":null,"attempts":105,"target":35,"unit_vi":"bóng","steps":["Từ fringe: flop, bump & run, chip thường vào khăn 15 ft (mỗi kiểu 15): đạt 15/45","Từ rough 5 y: 3 kiểu cú vào khăn 15 ft (mỗi kiểu 10): đạt 10/30","Up & down bằng 3 kiểu cú (mỗi kiểu 10): đạt 10/30"],"tags":["ladder-chip"],"audience":"all","sort_order":1003},{"code":"ladder-chip-4","title_vi":"Thang chip bậc 4","skill":"chip","contexts":["range"],"minutes":null,"attempts":120,"target":60,"unit_vi":"bóng","steps":["Từ fringe: dừng trong 3 ft tới lỗ 10, 30, 50 ft (mỗi lỗ 15): đạt 25/45","Từ rough 5 y: lỗ 15–20, 30–40, 50–60 ft, dừng trong 3 ft: đạt 20/45","Up & down lỗ gần, giữa, xa (mỗi lỗ 10): đạt 15/30"],"tags":["ladder-chip"],"audience":"all","sort_order":1004},{"code":"ladder-chip-5","title_vi":"Thang chip bậc 5","skill":"chip","contexts":["range"],"minutes":null,"attempts":105,"target":53,"unit_vi":"bóng","steps":["Từ rough cách green khoảng 7 y: bump & run tới lỗ 30–35, 45–50, 60–75 ft, trong 3 ft: đạt 23/45","Như trên bằng flop: đạt 15/30","Up & down lỗ gần, giữa, xa (mỗi lỗ 10): đạt 15/30"],"tags":["ladder-chip"],"audience":"all","sort_order":1005},{"code":"ladder-chip-6","title_vi":"Thang chip bậc 6","skill":"chip","contexts":["range"],"minutes":null,"attempts":110,"target":60,"unit_vi":"bóng","steps":["Một lỗ, chip từ 4 phía green, dừng trong 3 ft (mỗi phía 20): đạt 40/80","Up & down lỗ gần, giữa, xa (mỗi lỗ 10): đạt 20/30"],"tags":["ladder-chip"],"audience":"all","sort_order":1006},{"code":"ladder-chip-7","title_vi":"Thang chip bậc 7","skill":"chip","contexts":["range"],"minutes":null,"attempts":50,"target":40,"unit_vi":"bóng","steps":["50 up & down, mỗi lần một bóng, mỗi lần một vị trí và thế bóng khác: đạt 40/50"],"tags":["ladder-chip"],"audience":"all","sort_order":1007},{"code":"ladder-chip-8","title_vi":"Thang chip bậc 8","skill":"chip","contexts":["range"],"minutes":null,"attempts":85,"target":21,"unit_vi":"bóng","steps":["Flop và bump & run từ rough, chip thường từ fringe, dừng trong 3 ft (mỗi kiểu 10): đạt 15/30","5 up & down, mỗi lần một bóng: đạt 4/5","Chip vào lỗ 2 lần (1 từ fringe, 1 từ rough), tối đa 50 lượt: đạt 2/50"],"tags":["ladder-chip"],"audience":"all","sort_order":1008},{"code":"ladder-chip-9","title_vi":"Thang chip bậc 9","skill":"chip","contexts":["range"],"minutes":null,"attempts":128,"target":28,"unit_vi":"bóng","steps":["Slam dunk: chip bay thẳng vào lỗ (làm đủ lượt là qua): đạt 0/30","18 up & down ngẫu nhiên như 18 hố: đạt 11/18","Chip vào lỗ 2 lần, tối đa 50 lượt: đạt 2/50","Bump & run từ rough 3 y và 8 y tới lỗ xa, trong 3 ft: đạt 15/30"],"tags":["ladder-chip"],"audience":"all","sort_order":1009},{"code":"ladder-chip-10","title_vi":"Thang chip bậc 10","skill":"chip","contexts":["range"],"minutes":null,"attempts":110,"target":46,"unit_vi":"bóng","steps":["Từ rough: flop tới lỗ 30 ft, bump & run 40 ft, chip thường 20 ft, trong 3 ft (mỗi kiểu 10): đạt 24/30","Chip vào lỗ giữa green 2 lần, tối đa 50 lượt: đạt 2/50","Từ rough: chip vào khăn 10 ft và 20 ft (mỗi mốc 15): đạt 20/30"],"tags":["ladder-chip"],"audience":"all","sort_order":1010},{"code":"ladder-putt-1","title_vi":"Thang putt bậc 1","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":85,"unit_vi":"bóng","steps":["Cự ly gần 2–3 ft: một tay phải, một tay trái, hai phía lỗ, putt phẳng (mỗi bài 10): đạt 43/50","5 ft: lên dốc, xuống dốc, bẻ trái, bẻ phải, phẳng: đạt 22/50","10 ft: 4 kiểu dốc: đạt 4/40","15–20 ft: bẻ trái, bẻ phải: đạt 2/40","Lag 30 và 45 ft, dừng trong 3 ft: đạt 14/20"],"tags":["ladder-putt"],"audience":"all","sort_order":1021},{"code":"ladder-putt-2","title_vi":"Thang putt bậc 2","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":143,"unit_vi":"bóng","steps":["3 ft: tay phải, tay trái, hai tay: đạt 26/30","4 ft: 5 kiểu dốc: đạt 38/50","6 ft: 5 kiểu dốc: đạt 25/50","Lag 25–55 ft bẻ trái, bẻ phải, trong 3 ft: đạt 54/70"],"tags":["ladder-putt"],"audience":"all","sort_order":1022},{"code":"ladder-putt-3","title_vi":"Thang putt bậc 3","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":148,"unit_vi":"bóng","steps":["3 ft: lên dốc, xuống dốc, phẳng: đạt 28/30","4 ft: 4 kiểu: đạt 32/40","5 ft: 4 kiểu: đạt 25/40","6 ft: 4 kiểu: đạt 23/40","Lag 20–40 ft, trong 3 ft: đạt 40/50"],"tags":["ladder-putt"],"audience":"all","sort_order":1023},{"code":"ladder-putt-4","title_vi":"Thang putt bậc 4","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":139,"unit_vi":"bóng","steps":["3 ft: 3 kiểu: đạt 28/30","4 ft: 3 kiểu: đạt 24/30","5 ft: 3 kiểu: đạt 20/30","6 ft: 4 kiểu: đạt 24/40","8 ft: 3 kiểu: đạt 10/30","Lag 30–40 ft: đạt 33/40"],"tags":["ladder-putt"],"audience":"all","sort_order":1024},{"code":"ladder-putt-5","title_vi":"Thang putt bậc 5","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":137,"unit_vi":"bóng","steps":["3 ft: 3 kiểu: đạt 29/30","5 ft: 3 kiểu: đạt 22/30","6 ft: 3 kiểu: đạt 20/30","7 ft: 4 kiểu: đạt 18/40","8 ft: 3 kiểu: đạt 12/30","Lag 30–50 ft: đạt 36/40"],"tags":["ladder-putt"],"audience":"all","sort_order":1025},{"code":"ladder-putt-6","title_vi":"Thang putt bậc 6","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":128,"unit_vi":"bóng","steps":["3 ft: bẻ trái, bẻ phải, xuống dốc: đạt 30/30","5 ft: 3 kiểu: đạt 24/30","7 ft: 3 kiểu: đạt 16/30","9 ft: 4 kiểu: đạt 16/40","12 ft: 3 kiểu: đạt 6/30","Lag 25–45 ft: đạt 36/40"],"tags":["ladder-putt"],"audience":"all","sort_order":1026},{"code":"ladder-putt-7","title_vi":"Thang putt bậc 7","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":143,"unit_vi":"bóng","steps":["4 ft: 3 kiểu: đạt 28/30","5 ft: 3 kiểu: đạt 26/30","6 ft: 3 kiểu: đạt 22/30","8 ft: 4 kiểu: đạt 20/40","10 ft: 3 kiểu: đạt 10/30","Lag 40–55 ft: đạt 37/40"],"tags":["ladder-putt"],"audience":"all","sort_order":1027},{"code":"ladder-putt-8","title_vi":"Thang putt bậc 8","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":151,"unit_vi":"bóng","steps":["3–4 ft lên dốc và xuống dốc: đạt 40/40","6 ft: 3 kiểu: đạt 24/30","7 ft: 4 kiểu: đạt 30/40","9 ft bẻ trái, bẻ phải: đạt 10/20","12 ft: 3 kiểu: đạt 9/30","Lag 35–60 ft: đạt 38/40"],"tags":["ladder-putt"],"audience":"all","sort_order":1028},{"code":"ladder-putt-9","title_vi":"Thang putt bậc 9","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":145,"unit_vi":"bóng","steps":["3–4 ft lên dốc và xuống dốc: đạt 40/40","6 ft bẻ trái, bẻ phải: đạt 16/20","8 ft: 4 kiểu: đạt 26/40","10 ft: 4 kiểu: đạt 18/40","12 ft bẻ trái, bẻ phải: đạt 6/20","Lag 25–60 ft: đạt 39/40"],"tags":["ladder-putt"],"audience":"all","sort_order":1029},{"code":"ladder-putt-10","title_vi":"Thang putt bậc 10","skill":"putt","contexts":["range"],"minutes":null,"attempts":200,"target":131,"unit_vi":"bóng","steps":["5 ft: 4 kiểu: đạt 35/40","9 ft bẻ trái, bẻ phải: đạt 10/20","12 ft: 3 kiểu: đạt 12/30","6 ft bẻ trái, bẻ phải: đạt 16/20","15 ft bẻ trái, bẻ phải: đạt 8/40","Lag 25–60 ft: đạt 50/50"],"tags":["ladder-putt"],"audience":"all","sort_order":1030}]}$json$::jsonb; r jsonb;
begin
  for r in select * from jsonb_array_elements(d -> 'challenges') loop
    insert into public.training_challenges (level_number, code, kind, area, title_vi, how_vi, parts, verify, points_rank, points_reward, is_provisional, sort_order)
    values ((r ->> 'level_number')::int, r ->> 'code', r ->> 'kind', r ->> 'area', r ->> 'title_vi', r ->> 'how_vi', r -> 'parts', r ->> 'verify',
            30, 30, (r ->> 'is_provisional')::boolean, (r ->> 'sort_order')::int);
  end loop;
  for r in select * from jsonb_array_elements(d -> 'drills') loop
    insert into public.training_drills (code, title_vi, skill, audience, contexts, minutes, attempts, target, unit_vi, steps, tags, sort_order)
    values (r ->> 'code', r ->> 'title_vi', r ->> 'skill', r ->> 'audience',
            array(select jsonb_array_elements_text(r -> 'contexts')), (r ->> 'minutes')::int, (r ->> 'attempts')::int, (r ->> 'target')::int,
            r ->> 'unit_vi', r -> 'steps', array(select jsonb_array_elements_text(r -> 'tags')), (r ->> 'sort_order')::int);
  end loop;
end $$;
